where.if:
AND products.category_id IN (
    WITH RECURSIVE subcategories AS (
        SELECT category_id FROM categories WHERE category_id = #{categoryId}
        UNION ALL
        SELECT c.category_id FROM categories c
        INNER JOIN subcategories s ON c.parent_id = s.category_id
    )
    SELECT category_id FROM subcategories
)

mapper.update:
UPDATE products
SET stock = #{stock}
WHERE product_id = #{productId}

mapper.select:
SELECT p.product_id, p.category_id, p.name, p.description, p.price, p.discount_price, p.stock, p.image_url, p.status, p.created_at
FROM orders_item oi1
INNER JOIN orders_item oi2 ON oi1.order_id = oi2.order_id
INNER JOIN products p ON oi2.product_id = p.product_id
WHERE oi1.product_id = #{productId}
  AND oi2.product_id != #{productId}
GROUP BY p.product_id, p.category_id, p.name, p.description, p.price, p.discount_price, p.stock, p.image_url, p.status, p.created_at
ORDER BY COUNT(oi2.order_item_id) DESC
LIMIT #{limit}

SELECT p.product_id, p.category_id, p.name, p.description, p.price, p.discount_price, p.stock, p.image_url, p.status, p.created_at
FROM products p
INNER JOIN categories c ON p.category_id = c.category_id
WHERE p.product_id != #{productId}
  AND (
    c.parent_id = (SELECT parent_id FROM categories WHERE category_id = #{categoryId} AND parent_id IS NOT NULL)
    OR (SELECT parent_id FROM categories WHERE category_id = #{categoryId}) IS NULL
  )
ORDER BY p.product_id DESC
LIMIT #{limit}
